const t=JSON.parse('[{"id":"gallery.art.signs.c01","legacyId":"15ogohb","hall":"gallery","domain":"art","topic":"art.signs","level":12,"subjects":["art"],"sources":[{"title":"National Gallery, Glossary: Gothic","url":"https://www.nationalgallery.org.uk/paintings/glossary/gothic"},{"title":"Wikipedia: Middle Ages","url":"https://en.wikipedia.org/wiki/Middle_Ages"},{"title":"Tate Art Terms: Renaissance","url":"https://www.tate.org.uk/art/art-terms/r/renaissance"},{"title":"Tate Art Terms: Baroque","url":"https://www.tate.org.uk/art/art-terms/b/baroque"},{"title":"Tate Art Terms: Iconography","url":"https://www.tate.org.uk/art/art-terms/i/iconography"},{"title":"Wikipedia: Hierarchical proportion","url":"https://en.wikipedia.org/wiki/Hierarchical_proportion"}],"review":{"status":"legacy","fixes":["E001","E002","E003","E004","E005"]},"kind":"card","format":"choice","category":"признаци","prompt":"Златен фон, плоски фигури без сянка, по-важният персонаж е нарисуван по-едър. Кой период?","options":[{"text":"Готика (Gothic)"},{"text":"Средновековие (Middle Ages)"},{"text":"Ренесанс (Renaissance)"},{"text":"Барок (Baroque)"}],"answer":1,"explain":"Златният фон не е пространство, а знак за небесното. Плоскостта и йерархичният мащаб (hierarchical scale) са сърцевината на средновековната иконография (iconography) — наблюдението на натурата идва чак с готиката и Джото."},{"id":"gallery.art.signs.c02","legacyId":"1vsck4u","hall":"gallery","domain":"art","topic":"art.signs","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Renaissance","url":"https://www.tate.org.uk/art/art-terms/r/renaissance"},{"title":"Tate Art Terms: Romanticism","url":"https://www.tate.org.uk/art/art-terms/r/romanticism"},{"title":"Tate Art Terms: Baroque","url":"https://www.tate.org.uk/art/art-terms/b/baroque"},{"title":"Tate Art Terms: Neoclassicism","url":"https://www.tate.org.uk/art/art-terms/n/neoclassicism"},{"title":"Tate Art Terms: Chiaroscuro","url":"https://www.tate.org.uk/art/art-terms/c/chiaroscuro"}],"review":{"status":"legacy","fixes":["E006","E007","E008","E009","E010"]},"kind":"card","format":"choice","category":"признаци","prompt":"Един източник светлина, дълбок мрак наоколо, диагонално движение, сцената е спряна в кулминационната секунда.","options":[{"text":"Барок (Baroque)"},{"text":"Ренесанс (Renaissance)"},{"text":"Романтизъм (Romanticism)"},{"text":"Неокласицизъм (Neoclassicism)"}],"answer":0,"explain":"Това е кяроскурото (chiaroscuro) на Караваджо. Ренесансът осветява равномерно и търси равновесие; барокът избира една секунда и я осветява като прожектор."},{"id":"gallery.art.signs.c03","legacyId":"1rauqfn","hall":"gallery","domain":"art","topic":"art.signs","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Renaissance","url":"https://www.tate.org.uk/art/art-terms/r/renaissance"},{"title":"National Gallery, Glossary: Gothic","url":"https://www.nationalgallery.org.uk/paintings/glossary/gothic"},{"title":"Tate Art Terms: Realism","url":"https://www.tate.org.uk/art/art-terms/r/realism"},{"title":"Tate Art Terms: Cubism","url":"https://www.tate.org.uk/art/art-terms/c/cubism"},{"title":"National Gallery, Glossary: Linear perspective","url":"https://www.nationalgallery.org.uk/paintings/glossary/linear-perspective"}],"review":{"status":"legacy","fixes":["E011","E012","E013","E014","E015"]},"kind":"card","format":"choice","category":"признаци","prompt":"Ясен хоризонт с точка на схождане, симетрична архитектура, фигури в спокойно равновесие, ясно обозначен център.","options":[{"text":"Готика (Gothic)"},{"text":"Реализъм (Realism)"},{"text":"Кубизъм (Cubism)"},{"text":"Ренесанс (Renaissance)"}],"answer":3,"explain":"Линейната перспектива (Linear perspective) плюс равновесната композиция са подписът на Ренесанса. Погледни „Атинската школа“: всички линии се събират в две фигури в центъра."},{"id":"gallery.art.signs.c04","legacyId":"daajcg","hall":"gallery","domain":"art","topic":"art.signs","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Realism","url":"https://www.tate.org.uk/art/art-terms/r/realism"},{"title":"Tate Art Terms: Impressionism","url":"https://www.tate.org.uk/art/art-terms/i/impressionism"},{"title":"Tate Art Terms: Expressionism","url":"https://www.tate.org.uk/art/art-terms/e/expressionism"},{"title":"Tate Art Terms: Post-impressionism","url":"https://www.tate.org.uk/art/art-terms/p/post-impressionism"}],"review":{"status":"legacy","fixes":["E016","E017","E018","E019"]},"kind":"card","format":"choice","category":"признаци","prompt":"Къси видими мазки, цветни (не черни) сенки, обикновен момент от деня, светлината е истинският сюжет.","options":[{"text":"Реализъм (Realism)"},{"text":"Импресионизъм (Impressionism)"},{"text":"Експресионизъм (Expressionism)"},{"text":"Постимпресионизъм (Post-impressionism)"}],"answer":1,"explain":"Реализмът също рисува всекидневие, но със завършена повърхност и социална теза. Тук предметът е самата светлина в конкретен час."},{"id":"gallery.art.signs.c05","legacyId":"tt9wwj","hall":"gallery","domain":"art","topic":"art.signs","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Expressionism","url":"https://www.tate.org.uk/art/art-terms/e/expressionism"},{"title":"Tate Art Terms: Cubism","url":"https://www.tate.org.uk/art/art-terms/c/cubism"},{"title":"Tate Art Terms: Dada","url":"https://www.tate.org.uk/art/art-terms/d/dada"},{"title":"Tate Art Terms: Abstract expressionism","url":"https://www.tate.org.uk/art/art-terms/a/abstract-expressionism"}],"review":{"status":"legacy","fixes":["E020","E021","E022","E023"]},"kind":"card","format":"choice","category":"признаци","prompt":"Предметът е разглобен на плоскости и показан от няколко страни едновременно; цветът е сведен до сиво и охра.","options":[{"text":"Кубизъм (Cubism)"},{"text":"Експресионизъм (Expressionism)"},{"text":"Дада (Dada)"},{"text":"Абстрактен експресионизъм (Abstract expressionism)"}],"answer":0,"explain":"Кубизмът маха цвета нарочно, за да не пречи на главното: анализа на формата от няколко гледни точки в една плоскост."},{"id":"gallery.art.signs.c06","legacyId":"nnyx0u","hall":"gallery","domain":"art","topic":"art.signs","level":12,"subjects":["art"],"sources":[{"title":"Getty AAT: local color","url":"https://vocab.getty.edu/page/aat/300056135"},{"title":"Tate Art Terms: Pop art","url":"https://www.tate.org.uk/art/art-terms/p/pop-art"},{"title":"Tate Art Terms: Dada","url":"https://www.tate.org.uk/art/art-terms/d/dada"},{"title":"Tate Art Terms: Bauhaus","url":"https://www.tate.org.uk/art/art-terms/b/bauhaus"},{"title":"Tate Art Terms: Minimalism","url":"https://www.tate.org.uk/art/art-terms/m/minimalism"}],"review":{"status":"legacy","fixes":["E024","E025","E026","E027","E028"]},"kind":"card","format":"choice","category":"признаци","prompt":"Плосък локален цвят (local colour), черен контур, растерни точки, сюжет от комикс.","options":[{"text":"Дада (Dada)"},{"text":"Баухаус (Bauhaus)"},{"text":"Минимализъм (Minimalism)"},{"text":"Поп арт (Pop art)"}],"answer":3,"explain":"Растерната точка (Ben-Day) е знакът на печатната масова продукция. Лихтенщайн я рисува на ръка — художникът имитира машината."},{"id":"gallery.art.signs.c07","legacyId":"1ipkxik","hall":"gallery","domain":"art","topic":"art.signs","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Conceptual art","url":"https://www.tate.org.uk/art/art-terms/c/conceptual-art"},{"title":"Tate Art Terms: Minimalism","url":"https://www.tate.org.uk/art/art-terms/m/minimalism"},{"title":"Tate Art Terms: Bauhaus","url":"https://www.tate.org.uk/art/art-terms/b/bauhaus"},{"title":"Tate Art Terms: Abstract expressionism","url":"https://www.tate.org.uk/art/art-terms/a/abstract-expressionism"}],"review":{"status":"legacy","fixes":["E029","E030","E031","E032"]},"kind":"card","format":"choice","category":"признаци","prompt":"Еднакви прости модули, повторени в редица; индустриален материал; никаква следа от ръката на автора.","options":[{"text":"Концептуално изкуство (Conceptual art)"},{"text":"Минимализъм (Minimalism)"},{"text":"Баухаус (Bauhaus)"},{"text":"Абстрактен експресионизъм (Abstract expressionism)"}],"answer":1,"explain":"Баухаус също е геометричен, но проектира предмет с функция. Минимализмът прави обект, който не представя нищо освен себе си и пространството около зрителя."},{"id":"gallery.art.signs.c08","legacyId":"9iz8lv","hall":"gallery","domain":"art","topic":"art.signs","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Surrealism","url":"https://www.tate.org.uk/art/art-terms/s/surrealism"},{"title":"Tate Art Terms: Dada","url":"https://www.tate.org.uk/art/art-terms/d/dada"},{"title":"Tate Art Terms: Pop art","url":"https://www.tate.org.uk/art/art-terms/p/pop-art"},{"title":"Tate Art Terms: Expressionism","url":"https://www.tate.org.uk/art/art-terms/e/expressionism"},{"title":"Tate Art Terms: Photomontage","url":"https://www.tate.org.uk/art/art-terms/p/photomontage"}],"review":{"status":"legacy","fixes":["E033","E034","E035","E036","E037"]},"kind":"card","format":"choice","category":"признаци","prompt":"Изрязани снимки и букви от вестник, нарочно нарушена логика, политически гняв след световна война.","options":[{"text":"Сюрреализъм (Surrealism)"},{"text":"Поп арт (Pop art)"},{"text":"Експресионизъм (Expressionism)"},{"text":"Дада (Dada)"}],"answer":3,"explain":"Фотомонтажът (Photomontage) е дада изобретение. Сюрреализмът ще наследи странните съчетания, но ще ги рисува гладко и ще ги обясни с подсъзнанието, не с гнева."},{"id":"gallery.art.signs.c09","legacyId":"xbznpj","hall":"gallery","domain":"art","topic":"art.signs","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Dada","url":"https://www.tate.org.uk/art/art-terms/d/dada"},{"title":"Tate Art Terms: Surrealism","url":"https://www.tate.org.uk/art/art-terms/s/surrealism"},{"title":"Tate Art Terms: Expressionism","url":"https://www.tate.org.uk/art/art-terms/e/expressionism"},{"title":"Tate Art Terms: Pop art","url":"https://www.tate.org.uk/art/art-terms/p/pop-art"}],"review":{"status":"legacy","fixes":["E038","E039","E040","E041"]},"kind":"card","format":"choice","category":"признаци","prompt":"Обикновени предмети в невъзможно съчетание, нарисувани с почти фотографска точност.","options":[{"text":"Сюрреализъм (Surrealism)"},{"text":"Дада (Dada)"},{"text":"Експресионизъм (Expressionism)"},{"text":"Поп арт (Pop art)"}],"answer":0,"explain":"Точността е нарочна: колкото по-достоверно е нарисувано невъзможното, толкова по-силно работи като сън."},{"id":"gallery.art.signs.c10","legacyId":"imatdt","hall":"gallery","domain":"art","topic":"art.signs","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Neoclassicism","url":"https://www.tate.org.uk/art/art-terms/n/neoclassicism"},{"title":"Tate Art Terms: Romanticism","url":"https://www.tate.org.uk/art/art-terms/r/romanticism"},{"title":"Tate Art Terms: Realism","url":"https://www.tate.org.uk/art/art-terms/r/realism"},{"title":"Tate Art Terms: Baroque","url":"https://www.tate.org.uk/art/art-terms/b/baroque"}],"review":{"status":"legacy","fixes":["E042","E043","E044","E045"]},"kind":"card","format":"choice","category":"признаци","prompt":"Буря, нощ, руини; дребна човешка фигура пред огромна природа; свободна четка и драматична светлина.","options":[{"text":"Неокласицизъм (Neoclassicism)"},{"text":"Реализъм (Realism)"},{"text":"Романтизъм (Romanticism)"},{"text":"Барок (Baroque)"}],"answer":2,"explain":"Романтизмът е реакция срещу студения ред на неокласицизма: чувството, природата и въображението стават по-важни от правилото."},{"id":"gallery.art.signs.c11","legacyId":"lr4h3e","hall":"gallery","domain":"art","topic":"art.signs","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Impressionism","url":"https://www.tate.org.uk/art/art-terms/i/impressionism"},{"title":"Tate Art Terms: Post-impressionism","url":"https://www.tate.org.uk/art/art-terms/p/post-impressionism"},{"title":"Tate Art Terms: Expressionism","url":"https://www.tate.org.uk/art/art-terms/e/expressionism"},{"title":"Tate Art Terms: Surrealism","url":"https://www.tate.org.uk/art/art-terms/s/surrealism"}],"review":{"status":"legacy","fixes":["E046","E047","E048","E049"]},"kind":"card","format":"choice","category":"признаци","prompt":"Сини коне и зелено небе — цветът очевидно не описва предмета, а състоянието.","options":[{"text":"Импресионизъм (Impressionism)"},{"text":"Постимпресионизъм (Post-impressionism)"},{"text":"Сюрреализъм (Surrealism)"},{"text":"Експресионизъм (Expressionism)"}],"answer":3,"explain":"При експресионизма цветът е емоционален код. Франц Марк дава на синьото значение на духовно и мъжко начало — животното е символ, не модел."},{"id":"gallery.art.signs.c12","legacyId":"1tg8lof","hall":"gallery","domain":"art","topic":"art.signs","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Abstract expressionism","url":"https://www.tate.org.uk/art/art-terms/a/abstract-expressionism"},{"title":"Tate Art Terms: Cubism","url":"https://www.tate.org.uk/art/art-terms/c/cubism"},{"title":"Tate Art Terms: Minimalism","url":"https://www.tate.org.uk/art/art-terms/m/minimalism"},{"title":"Tate Art Terms: Dada","url":"https://www.tate.org.uk/art/art-terms/d/dada"}],"review":{"status":"legacy","fixes":["E050","E051","E052","E053"]},"kind":"card","format":"choice","category":"признаци","prompt":"Огромно платно, следата на жеста е самият сюжет, няма разпознаваем предмет.","options":[{"text":"Кубизъм (Cubism)"},{"text":"Минимализъм (Minimalism)"},{"text":"Дада (Dada)"},{"text":"Абстрактен експресионизъм (Abstract expressionism)"}],"answer":3,"explain":"Минимализмът също е безпредметен, но е хладен и фабричен. Тук всичко е следа от тяло и движение в момента на рисуване."},{"id":"gallery.art.signs.c13","legacyId":"dx6rrs","hall":"gallery","domain":"art","topic":"art.signs","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Renaissance","url":"https://www.tate.org.uk/art/art-terms/r/renaissance"},{"title":"National Gallery, Glossary: Linear perspective","url":"https://www.nationalgallery.org.uk/paintings/glossary/linear-perspective"}],"review":{"status":"legacy","fixes":["E054","E055"]},"kind":"card","format":"choice","category":"признаци","prompt":"Кое НЕ е типично за Ренесанса (Renaissance)?","options":[{"text":"Златен фон без дълбочина"},{"text":"Линейна перспектива (Linear perspective)"},{"text":"Анатомия и пропорция"},{"text":"Композиция в равновесие"}],"answer":0,"explain":"Златният фон е средновековен. Ренесансът точно него заменя с измеримо пространство."},{"id":"gallery.art.signs.c14","legacyId":"6ag9zx","hall":"gallery","domain":"art","topic":"art.signs","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Minimalism","url":"https://www.tate.org.uk/art/art-terms/m/minimalism"}],"review":{"status":"legacy","fixes":["E056"]},"kind":"card","format":"choice","category":"признаци","prompt":"Кое НЕ е типично за минимализма (Minimalism)?","options":[{"text":"Повторение на еднакви модули"},{"text":"Индустриални материали"},{"text":"Експресивна следа на четката"},{"text":"Неутрален цвят"}],"answer":2,"explain":"Експресивната следа е точно това, от което минимализмът бяга — тя връща автора и емоцията в творбата."},{"id":"gallery.art.signs.c15","legacyId":"1uqqwor","hall":"gallery","domain":"art","topic":"art.signs","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Baroque","url":"https://www.tate.org.uk/art/art-terms/b/baroque"},{"title":"Tate Art Terms: Neoclassicism","url":"https://www.tate.org.uk/art/art-terms/n/neoclassicism"}],"review":{"status":"legacy","fixes":["E057","E058"]},"kind":"card","format":"choice","category":"признаци","prompt":"Кое НЕ е типично за барока (Baroque)?","options":[{"text":"Силен светлинен контраст"},{"text":"Плитка релефна сцена и скрита четка"},{"text":"Диагонална композиция"},{"text":"Емоционална кулминация"}],"answer":1,"explain":"Плитката сцена и гладката, скрита четка са неокласицизъм (Neoclassicism) — редът срещу бароковата буря."},{"id":"gallery.art.works.c01","legacyId":"10rh45v","hall":"gallery","domain":"art","topic":"art.works","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Baroque","url":"https://www.tate.org.uk/art/art-terms/b/baroque"},{"title":"Tate Art Terms: Renaissance","url":"https://www.tate.org.uk/art/art-terms/r/renaissance"},{"title":"Tate Art Terms: Neoclassicism","url":"https://www.tate.org.uk/art/art-terms/n/neoclassicism"},{"title":"National Gallery, Glossary: Gothic","url":"https://www.nationalgallery.org.uk/paintings/glossary/gothic"},{"title":"Getty AAT: High Renaissance","url":"https://vocab.getty.edu/page/aat/300021142"}],"review":{"status":"legacy","fixes":["E059","E060","E061","E062","E063"]},"kind":"card","format":"choice","category":"произведения","prompt":"„Атинската школа“ (Рафаело) — кой период?","options":[{"text":"Ренесанс (Renaissance)"},{"text":"Барок (Baroque)"},{"text":"Неокласицизъм (Neoclassicism)"},{"text":"Готика (Gothic)"}],"answer":0,"explain":"Висок Ренесанс (High Renaissance), 1509–1511, Ватикана. Цялата архитектура е построена така, че перспективата да събере погледа върху Платон и Аристотел."},{"id":"gallery.art.works.c02","legacyId":"1v75zrh","hall":"gallery","domain":"art","topic":"art.works","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Neoclassicism","url":"https://www.tate.org.uk/art/art-terms/n/neoclassicism"},{"title":"Tate Art Terms: Baroque","url":"https://www.tate.org.uk/art/art-terms/b/baroque"},{"title":"Tate Art Terms: Romanticism","url":"https://www.tate.org.uk/art/art-terms/r/romanticism"},{"title":"Tate Art Terms: Realism","url":"https://www.tate.org.uk/art/art-terms/r/realism"}],"review":{"status":"legacy","fixes":["E064","E065","E066","E067"]},"kind":"card","format":"choice","category":"произведения","prompt":"„Смъртта на Сократ“ (Жак-Луи Давид, 1787) — кой период?","options":[{"text":"Барок (Baroque)"},{"text":"Неокласицизъм (Neoclassicism)"},{"text":"Романтизъм (Romanticism)"},{"text":"Реализъм (Realism)"}],"answer":1,"explain":"Античен сюжет, релефна композиция, ясен контур, морален урок — и две години преди Френската революция това е политическо послание."},{"id":"gallery.art.works.c03","legacyId":"89yudj","hall":"gallery","domain":"art","topic":"art.works","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Dada","url":"https://www.tate.org.uk/art/art-terms/d/dada"},{"title":"Tate Art Terms: Surrealism","url":"https://www.tate.org.uk/art/art-terms/s/surrealism"},{"title":"Tate Art Terms: Expressionism","url":"https://www.tate.org.uk/art/art-terms/e/expressionism"},{"title":"Tate Art Terms: Pop art","url":"https://www.tate.org.uk/art/art-terms/p/pop-art"}],"review":{"status":"legacy","fixes":["E068","E069","E070","E071"]},"kind":"card","format":"choice","category":"произведения","prompt":"„Постоянството на паметта“ (Салвадор Дали) — кой период?","options":[{"text":"Дада (Dada)"},{"text":"Експресионизъм (Expressionism)"},{"text":"Сюрреализъм (Surrealism)"},{"text":"Поп арт (Pop art)"}],"answer":2,"explain":"1931 г. Меките часовници са невъзможен предмет, нарисуван с абсолютна точност — логиката на съня."},{"id":"gallery.art.works.c04","legacyId":"9sg6tw","hall":"gallery","domain":"art","topic":"art.works","level":12,"subjects":["art"],"sources":[{"title":"MoMA: Roy Lichtenstein, Drowning Girl, 1963","url":"https://www.moma.org/collection/works/80249"},{"title":"Tate Art Terms: Pop art","url":"https://www.tate.org.uk/art/art-terms/p/pop-art"},{"title":"Tate Art Terms: Dada","url":"https://www.tate.org.uk/art/art-terms/d/dada"},{"title":"Tate Art Terms: Abstract expressionism","url":"https://www.tate.org.uk/art/art-terms/a/abstract-expressionism"},{"title":"Tate Art Terms: Conceptual art","url":"https://www.tate.org.uk/art/art-terms/c/conceptual-art"}],"review":{"status":"legacy","fixes":["G001","E072","E073","E074","E075"]},"kind":"card","format":"choice","category":"произведения","prompt":"„Давещото се момиче“ (Рой Лихтенщайн, 1963) — кой период?","options":[{"text":"Поп арт (Pop art)"},{"text":"Дада (Dada)"},{"text":"Абстрактен експресионизъм (Abstract expressionism)"},{"text":"Концептуално изкуство (Conceptual art)"}],"answer":0,"explain":"Кадър от любовен комикс, увеличен до размера на историческа картина: евтиният източник и високият жанр се сблъскват."},{"id":"gallery.art.works.c05","legacyId":"1s1g5nq","hall":"gallery","domain":"art","topic":"art.works","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Impressionism","url":"https://www.tate.org.uk/art/art-terms/i/impressionism"},{"title":"Tate Art Terms: Post-impressionism","url":"https://www.tate.org.uk/art/art-terms/p/post-impressionism"},{"title":"Tate Art Terms: Expressionism","url":"https://www.tate.org.uk/art/art-terms/e/expressionism"},{"title":"Tate Art Terms: Realism","url":"https://www.tate.org.uk/art/art-terms/r/realism"}],"review":{"status":"legacy","fixes":["E076","E077","E078","E079"]},"kind":"card","format":"choice","category":"произведения","prompt":"„Житно поле с кипариси“ (Ван Гог, 1889) — кой период?","options":[{"text":"Импресионизъм (Impressionism)"},{"text":"Постимпресионизъм (Post-impressionism)"},{"text":"Експресионизъм (Expressionism)"},{"text":"Реализъм (Realism)"}],"answer":1,"explain":"Импресионистична мазка, но подчинена на вътрешното състояние: полето и небето се движат като едно тяло."},{"id":"gallery.art.works.c06","legacyId":"1ea6tna","hall":"gallery","domain":"art","topic":"art.works","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Expressionism","url":"https://www.tate.org.uk/art/art-terms/e/expressionism"},{"title":"Tate Art Terms: Cubism","url":"https://www.tate.org.uk/art/art-terms/c/cubism"},{"title":"Tate Art Terms: Fauvism","url":"https://www.tate.org.uk/art/art-terms/f/fauvism"},{"title":"Tate Art Terms: Surrealism","url":"https://www.tate.org.uk/art/art-terms/s/surrealism"}],"review":{"status":"legacy","fixes":["E080","E081","E082","E083"]},"kind":"card","format":"choice","category":"произведения","prompt":"„Сините коне“ (Франц Марк, 1911) — кой период?","options":[{"text":"Кубизъм (Cubism)"},{"text":"Фовизъм (Fauvism)"},{"text":"Сюрреализъм (Surrealism)"},{"text":"Експресионизъм (Expressionism)"}],"answer":3,"explain":"Марк е от групата „Синият конник“ (Der Blaue Reiter) — немски експресионизъм. Фовизмът също е с ярък цвят, но е френски и с друга, по-декоративна нагласа."},{"id":"gallery.art.works.c07","legacyId":"3gfqgp","hall":"gallery","domain":"art","topic":"art.works","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Bauhaus","url":"https://www.tate.org.uk/art/art-terms/b/bauhaus"},{"title":"Tate Art Terms: Dada","url":"https://www.tate.org.uk/art/art-terms/d/dada"},{"title":"Tate Art Terms: Constructivism","url":"https://www.tate.org.uk/art/art-terms/c/constructivism"},{"title":"Tate Art Terms: Surrealism","url":"https://www.tate.org.uk/art/art-terms/s/surrealism"}],"review":{"status":"legacy","fixes":["E084","E085","E086","E087"]},"kind":"card","format":"choice","category":"произведения","prompt":"„Механична глава (Духът на нашето време)“ (Раул Хаусман) — кой период?","options":[{"text":"Дада (Dada)"},{"text":"Баухаус (Bauhaus)"},{"text":"Конструктивизъм (Constructivism)"},{"text":"Сюрреализъм (Surrealism)"}],"answer":0,"explain":"Ок. 1920 г. Дървена глава на перукер, облепена с измервателни уреди: човекът като автомат на своето време."},{"id":"gallery.art.works.c08","legacyId":"1prqh2y","hall":"gallery","domain":"art","topic":"art.works","level":12,"subjects":["art"],"sources":[{"title":"National Gallery, Glossary: Gothic","url":"https://www.nationalgallery.org.uk/paintings/glossary/gothic"},{"title":"Wikipedia: Middle Ages","url":"https://en.wikipedia.org/wiki/Middle_Ages"},{"title":"Tate Art Terms: Renaissance","url":"https://www.tate.org.uk/art/art-terms/r/renaissance"},{"title":"Wikipedia: Bulgarian Revival","url":"https://en.wikipedia.org/wiki/Bulgarian_National_Revival"}],"review":{"status":"legacy","fixes":["E088","E089","E090","E091"]},"kind":"card","format":"choice","category":"произведения","prompt":"Боянската църква (1259) с прочутите си стенописи спада към…","options":[{"text":"Готика (Gothic)"},{"text":"Ренесанс (Renaissance)"},{"text":"Средновековие (Middle Ages)"},{"text":"Възраждане (Bulgarian National Revival)"}],"answer":2,"explain":"Зряло средновековие. Лицата обаче са индивидуализирани — това е причината паметникът да е в списъка на ЮНЕСКО."},{"id":"gallery.art.chrono.c01","legacyId":"93agq6","hall":"gallery","domain":"art","topic":"art.chrono","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Dada","url":"https://www.tate.org.uk/art/art-terms/d/dada"},{"title":"Tate Art Terms: Cubism","url":"https://www.tate.org.uk/art/art-terms/c/cubism"},{"title":"Tate Art Terms: Bauhaus","url":"https://www.tate.org.uk/art/art-terms/b/bauhaus"},{"title":"Tate Art Terms: Surrealism","url":"https://www.tate.org.uk/art/art-terms/s/surrealism"}],"review":{"status":"legacy","fixes":["E092","E093","E094","E095"]},"kind":"card","format":"choice","category":"хронология","prompt":"Кое от изброените се появява ПЪРВО?","options":[{"text":"Дада (Dada)"},{"text":"Баухаус (Bauhaus)"},{"text":"Кубизъм (Cubism)"},{"text":"Сюрреализъм (Surrealism)"}],"answer":2,"explain":"Кубизъм 1907 → Дада 1916 → Баухаус 1919 → Сюрреализъм 1924. Три от четирите са реакция на Първата световна война."},{"id":"gallery.art.chrono.c02","legacyId":"yri6a3","hall":"gallery","domain":"art","topic":"art.chrono","level":12,"subjects":["art"],"sources":[{"title":"National Gallery, Glossary: Gothic","url":"https://www.nationalgallery.org.uk/paintings/glossary/gothic"},{"title":"Tate Art Terms: Baroque","url":"https://www.tate.org.uk/art/art-terms/b/baroque"},{"title":"Tate Art Terms: Renaissance","url":"https://www.tate.org.uk/art/art-terms/r/renaissance"},{"title":"Tate Art Terms: Romanticism","url":"https://www.tate.org.uk/art/art-terms/r/romanticism"},{"title":"Wikipedia: Middle Ages","url":"https://en.wikipedia.org/wiki/Middle_Ages"}],"review":{"status":"legacy","fixes":["E096","E097","E098","E099","E100"]},"kind":"card","format":"choice","category":"хронология","prompt":"Кой период идва непосредствено СЛЕД готиката (Gothic)?","options":[{"text":"Барок (Baroque)"},{"text":"Романтизъм (Romanticism)"},{"text":"Ренесанс (Renaissance)"},{"text":"Средновековие (Middle Ages)"}],"answer":2,"explain":"Готиката и ранният Ренесанс дори се застъпват в Италия — Джото работи в края на готиката и вече мисли като ренесансов художник."},{"id":"gallery.art.chrono.c03","legacyId":"1iqfx43","hall":"gallery","domain":"art","topic":"art.chrono","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Impressionism","url":"https://www.tate.org.uk/art/art-terms/i/impressionism"},{"title":"Tate Art Terms: Realism","url":"https://www.tate.org.uk/art/art-terms/r/realism"},{"title":"Tate Art Terms: Post-impressionism","url":"https://www.tate.org.uk/art/art-terms/p/post-impressionism"},{"title":"Tate Art Terms: Expressionism","url":"https://www.tate.org.uk/art/art-terms/e/expressionism"}],"review":{"status":"legacy","fixes":["E101","E102","E103","E104"]},"kind":"card","format":"choice","category":"хронология","prompt":"Кое от изброените е НАЙ-РАНО?","options":[{"text":"Импресионизъм (Impressionism)"},{"text":"Реализъм (Realism)"},{"text":"Постимпресионизъм (Post-impressionism)"},{"text":"Експресионизъм (Expressionism)"}],"answer":1,"explain":"Реализъм 1848 → импресионизъм 1874 → постимпресионизъм 1885 → експресионизъм 1905. Всяко следващо се отблъсква от предишното."},{"id":"gallery.art.chrono.c04","legacyId":"16td1er","hall":"gallery","domain":"art","topic":"art.chrono","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Bauhaus","url":"https://www.tate.org.uk/art/art-terms/b/bauhaus"}],"review":{"status":"legacy","fixes":["E105"]},"kind":"card","format":"choice","category":"хронология","prompt":"Баухаус (Bauhaus) съществува като училище в годините…","options":[{"text":"1900–1914"},{"text":"1919–1933"},{"text":"1920–1925"},{"text":"1945–1960"}],"answer":1,"explain":"Ваймар (1919) → Десау (1925) → Берлин, закрито от нацистите през 1933 г. Част от източниците дават само годините на най-известните му плакати."},{"id":"gallery.art.concepts.c01","legacyId":"1tmpmwk","hall":"gallery","domain":"art","topic":"art.concepts","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Chiaroscuro","url":"https://www.tate.org.uk/art/art-terms/c/chiaroscuro"}],"review":{"status":"legacy","fixes":["E106"]},"kind":"card","format":"recall","category":"понятия","prompt":"Какво е кяроскуро (chiaroscuro) и какво ти дава в един кадър?","model":"Силен контраст между осветено и тъмно при един източник светлина. Дава обем, отвежда погледа към най-светлото петно и внася драма — същото, което в анимацията прави силен key light с дълбока сянка."},{"id":"gallery.art.concepts.c02","legacyId":"gmfvxw","hall":"gallery","domain":"art","topic":"art.concepts","level":12,"subjects":["art"],"sources":[{"title":"National Gallery, Glossary: Contrapposto","url":"https://www.nationalgallery.org.uk/paintings/glossary/contrapposto"},{"title":"Getty AAT: contrapposto","url":"https://vocab.getty.edu/page/aat/300067391"},{"title":"Tate Art Terms: Renaissance","url":"https://www.tate.org.uk/art/art-terms/r/renaissance"}],"review":{"status":"legacy","fixes":["E107","E108"]},"kind":"card","format":"recall","category":"понятия","prompt":"Какво е контрапост (contrapposto)?","model":"Стоеж с тежест върху единия крак: тазът и раменете се наклоняват в противоположни посоки, гръбнакът прави лека S-крива. Фигурата спира да бъде симетричен стълб и изглежда жива. Античен похват, преоткрит в Ренесанса (Renaissance)."},{"id":"gallery.art.concepts.c03","legacyId":"6n6spi","hall":"gallery","domain":"art","topic":"art.concepts","level":12,"subjects":["art"],"sources":[{"title":"National Gallery, Glossary: Sfumato","url":"https://www.nationalgallery.org.uk/paintings/glossary/sfumato"},{"title":"Getty AAT: sfumato","url":"https://vocab.getty.edu/page/aat/300053421"}],"review":{"status":"legacy","fixes":["E109"]},"kind":"card","format":"recall","category":"понятия","prompt":"Какво е сфумато (sfumato) и при кого го виждаш?","model":"Преход без контур: светло и тъмно се сливат през незабележими степени, „като дим“. Леонардо го използва в „Мона Лиза“ — оттам е неуловимото изражение."},{"id":"gallery.art.concepts.c04","legacyId":"1prevs3","hall":"gallery","domain":"art","topic":"art.concepts","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Readymade","url":"https://www.tate.org.uk/art/art-terms/r/readymade"},{"title":"Tate Art Terms: Conceptual art","url":"https://www.tate.org.uk/art/art-terms/c/conceptual-art"}],"review":{"status":"legacy","fixes":["E110","E111"]},"kind":"card","format":"recall","category":"понятия","prompt":"Какво е реди-мейд (readymade) и защо е важен за историята на изкуството?","model":"Готов, непроменен предмет, обявен за произведение — „Фонтан“ на Дюшан, 1917. Премества въпроса от „как е направено“ към „кой и къде го нарича изкуство“. Оттук тръгва концептуалното изкуство (Conceptual art)."},{"id":"gallery.art.concepts.c05","legacyId":"11jyge4","hall":"gallery","domain":"art","topic":"art.concepts","level":12,"subjects":["art"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","category":"понятия","prompt":"Кои са четирите стъпки при разчитане на произведение?","model":"1) Описание — какво виждам, без тълкуване. 2) Анализ на формата — композиция, светлина, цвят, пространство. 3) Интерпретация — какво означава и от какво в изображението го разбирам. 4) Контекст и оценка — кога и за кого е правено, как работи."},{"id":"gallery.art.concepts.c06","legacyId":"1mniv0o","hall":"gallery","domain":"art","topic":"art.concepts","level":12,"subjects":["art"],"sources":[{"title":"Wikipedia: Leading lines","url":"https://en.wikipedia.org/wiki/Leading_lines"}],"review":{"status":"legacy","fixes":["E112"]},"kind":"card","format":"recall","category":"понятия","prompt":"Изброй поне четири неща, които гледаш, когато анализираш композиция.","model":"Формат и ориентация; център или фокус и как е постигнат; водещи линии (leading lines) и диагонали; баланс и ритъм; планове и дълбочина; празно пространство; силует на фигурите."},{"id":"gallery.art.concepts.c07","legacyId":"ef34z1","hall":"gallery","domain":"art","topic":"art.concepts","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Post-impressionism","url":"https://www.tate.org.uk/art/art-terms/p/post-impressionism"},{"title":"Tate Art Terms: Impressionism","url":"https://www.tate.org.uk/art/art-terms/i/impressionism"}],"review":{"status":"legacy","fixes":["E113"]},"kind":"card","format":"recall","category":"понятия","prompt":"Каква е разликата между импресионизъм (Impressionism) и постимпресионизъм (Post-impressionism)?","model":"Импресионизмът гони външното: светлината в определен момент, видяна с окото. Постимпресионизмът тръгва от същата мазка, но я подчинява на вътрешното — цветът изразява състояние (Ван Гог, Гоген) или строи форма (Сезан, Сьора)."},{"id":"gallery.art.concepts.c08","legacyId":"1ve935i","hall":"gallery","domain":"art","topic":"art.concepts","level":12,"subjects":["art"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","category":"понятия","prompt":"Защо в готическата катедрала прозорците стават огромни?","model":"Стрелковидната арка и контрафорсите поемат тежестта на свода и я отвеждат встрани. Стената спира да носи и може да бъде заменена с витраж — светлината влиза в храма като цвят."},{"id":"gallery.art.concepts.c09","legacyId":"onn9f","hall":"gallery","domain":"art","topic":"art.concepts","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Conceptual art","url":"https://www.tate.org.uk/art/art-terms/c/conceptual-art"}],"review":{"status":"legacy","fixes":["E114"]},"kind":"card","format":"recall","category":"понятия","prompt":"Какво е концептуално изкуство (Conceptual art) и къде е произведението, ако не е в обекта?","model":"В идеята и в нейното формулиране. Обектът може да е инструкция, текст, снимка или документация на действие. Кошут, „Един и три стола“ (1965): истински стол, негова снимка и речниковото определение — трите заедно са въпросът „кое от тях е столът“."},{"id":"gallery.art.concepts.c10","legacyId":"12apgeh","hall":"gallery","domain":"art","topic":"art.concepts","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Bauhaus","url":"https://www.tate.org.uk/art/art-terms/b/bauhaus"}],"review":{"status":"legacy","fixes":["G009","E115"]},"kind":"card","format":"recall","category":"понятия","prompt":"С какво Баухаус (Bauhaus) променя дизайна?","model":"Свързва занаята с машинното производство: формата следва функцията, геометрия и ясна решетка, типографията е равностоен материал. Оттам идват модулната мрежа (Grid) и шрифтовата йерархия, с които работиш днес."},{"id":"gallery.art.transfer.c01","legacyId":"1ycoeur","hall":"gallery","domain":"art","topic":"art.transfer","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Chiaroscuro","url":"https://www.tate.org.uk/art/art-terms/c/chiaroscuro"}],"review":{"status":"legacy","fixes":["E116"]},"kind":"card","format":"recall","category":"пренос","prompt":"Кадърът ти изглежда плосък и скучен. Кои три инструмента от историята на изкуството прилагаш веднага?","model":"1) Кяроскуро (Chiaroscuro) — един силен източник и дълбока сянка вместо равномерно осветяване. 2) Диагонал вместо фронтална подредба. 3) Ограничен колорит с един комплементарен акцент. И проверка: чете ли се силуетът, ако запълниш всичко в черно."},{"id":"gallery.art.transfer.c02","legacyId":"1byw2t8","hall":"gallery","domain":"art","topic":"art.transfer","level":12,"subjects":["art"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","category":"пренос","prompt":"Как разчиташ посоката на светлината в една картина и какво ти казва тя?","model":"Виж от коя страна са светлите ръбове и накъде падат сенките, после намери най-светлото петно — там обикновено е фокусът. Посоката носи смисъл: отгоре е спокойно и „божествено“, отдолу е тревожно, отстрани дава релеф и обем."},{"id":"gallery.art.transfer.c03","legacyId":"vcl9z1","hall":"gallery","domain":"art","topic":"art.transfer","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Baroque","url":"https://www.tate.org.uk/art/art-terms/b/baroque"},{"title":"Tate Art Terms: Expressionism","url":"https://www.tate.org.uk/art/art-terms/e/expressionism"}],"review":{"status":"legacy","fixes":["B031","E117"]},"kind":"card","format":"recall","category":"пренос","prompt":"Правиш colour script за сцена с тревога. Кой период ти дава най-пряк инструмент и защо?","model":"Експресионизмът (Expressionism): цветът се избира заради състоянието, не заради предмета — зелено небе, сини коне, киселинни съчетания. Плюс барока (Baroque) за светлината: тесен лъч и голям мрак."},{"id":"gallery.art.transfer.c04","legacyId":"18jhr26","hall":"gallery","domain":"art","topic":"art.transfer","level":12,"subjects":["art"],"sources":[{"title":"Getty AAT: stylization","url":"https://vocab.getty.edu/page/aat/300055836"}],"review":{"status":"legacy","fixes":["E118"]},"kind":"card","format":"recall","category":"пренос","prompt":"Защо стилизацията (stylisation) не е „опростяване, защото не мога да нарисувам по-добре“?","model":"Стилизацията е избор какво да остане: свеждаш формата до най-носещия ѝ знак. За да знаеш кое да махнеш, трябва да познаваш формата — Сезан свежда всичко до цилиндър, конус и сфера; Лихтенщайн — до контур и точка."},{"id":"gallery.art.transfer.c05","legacyId":"bk95gu","hall":"gallery","domain":"art","topic":"art.transfer","level":12,"subjects":["art"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","category":"пренос","prompt":"Как използваш AI в едно задание, без да загубиш авторството си?","model":"Първо решаваш ти и го записваш: замисъл, референции, композиция, палитра. AI влиза после — за варианти, за проверка, за черната работа. Накрая отбелязваш какво е генерирано и защо си избрал точно него. Ако не можеш да обясниш избора си, решението не е твое."},{"id":"gallery.art.vocab.t01","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Composition","url":"https://www.tate.org.uk/art/art-terms/c/composition"}],"review":{"status":"legacy","fixes":["G010","G011","G012","G013"]},"kind":"term","term":{"label":"Композиция (Composition)","bg":"Композиция","en":"Composition","alts":["composition","композиция"],"def":"Подредбата на елементите в границите на формата — тя решава накъде тръгва погледът и къде спира."}},{"id":"gallery.art.vocab.t02","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Format","url":"https://www.tate.org.uk/art/art-terms/f/format"}],"review":{"status":"legacy","fixes":["G014","G015","G016","G017"]},"kind":"term","term":{"label":"Формат (Format)","bg":"Формат","en":"Format","alts":["format","формат"],"def":"Пропорцията и ориентацията на полето: вертикал, хоризонтал, квадрат. Задава настроението, преди в него да има каквото и да е."}},{"id":"gallery.art.vocab.t03","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Getty AAT: focal point","url":"https://vocab.getty.edu/page/aat/300056345"}],"review":{"status":"legacy","fixes":["G018","G019","G020","G021"]},"kind":"term","term":{"label":"Фокус (Focal point)","bg":"Фокус","en":"Focal point","alts":["focal point","фокус","акцент"],"def":"Точката, към която всичко води: най-силен контраст, най-ясен детайл, най-топъл цвят."}},{"id":"gallery.art.vocab.t04","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Wikipedia: Leading lines","url":"https://en.wikipedia.org/wiki/Leading_lines"}],"review":{"status":"legacy","fixes":["G022","G023","G024","G025"]},"kind":"term","term":{"label":"Водещи линии (Leading lines)","bg":"Водещи линии","en":"Leading lines","alts":["leading lines","водещи линии"],"def":"Реални или подразбиращи се линии — ръбове, жестове, погледи — които насочват окото на зрителя."}},{"id":"gallery.art.vocab.t05","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"National Gallery, Glossary: Contrapposto","url":"https://www.nationalgallery.org.uk/paintings/glossary/contrapposto"},{"title":"Getty AAT: contrapposto","url":"https://vocab.getty.edu/page/aat/300067391"}],"review":{"status":"legacy","fixes":["G026","G027","G028","G029"]},"kind":"term","term":{"label":"Контрапост (Contrapposto)","bg":"Контрапост","en":"Contrapposto","alts":["contrapposto","контрапост"],"def":"Стоеж с тежест върху единия крак; раменете и тазът се наклоняват в обратни посоки и фигурата оживява."}},{"id":"gallery.art.vocab.t06","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Chiaroscuro","url":"https://www.tate.org.uk/art/art-terms/c/chiaroscuro"}],"review":{"status":"legacy","fixes":["G030","G031","G032","G033"]},"kind":"term","term":{"label":"Кяроскуро (Chiaroscuro)","bg":"Кяроскуро","en":"Chiaroscuro","alts":["chiaroscuro","кяроскуро"],"def":"Рязък контраст между светлина и сянка при един източник; моделира обема и създава драма."}},{"id":"gallery.art.vocab.t07","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"National Gallery, Glossary: Sfumato","url":"https://www.nationalgallery.org.uk/paintings/glossary/sfumato"},{"title":"Getty AAT: sfumato","url":"https://vocab.getty.edu/page/aat/300053421"}],"review":{"status":"legacy","fixes":["G034","G035","G036","G037"]},"kind":"term","term":{"label":"Сфумато (Sfumato)","bg":"Сфумато","en":"Sfumato","alts":["sfumato","сфумато"],"def":"Размиване на контура през незабележими преходи, „като дим“. Похватът на Леонардо."}},{"id":"gallery.art.vocab.t08","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"National Gallery, Glossary: Linear perspective","url":"https://www.nationalgallery.org.uk/paintings/glossary/linear-perspective"}],"review":{"status":"legacy","fixes":["G038","G039","G040","G041"]},"kind":"term","term":{"label":"Линейна перспектива (Linear perspective)","bg":"Линейна перспектива","en":"Linear perspective","alts":["linear perspective","линейна перспектива"],"def":"Система с хоризонт и точка на схождане, която прави измеримо пространство върху плоскост."}},{"id":"gallery.art.vocab.t09","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"National Gallery, Glossary: Aerial perspective","url":"https://www.nationalgallery.org.uk/paintings/glossary/aerial-perspective"},{"title":"Getty AAT: atmospheric perspective","url":"https://vocab.getty.edu/page/aat/300133044"}],"review":{"status":"legacy","fixes":["G042","G043","G044","G045"]},"kind":"term","term":{"label":"Въздушна перспектива (Aerial perspective)","bg":"Въздушна перспектива","en":"Aerial perspective","alts":["aerial perspective","въздушна перспектива","atmospheric perspective"],"def":"Далечното става по-светло, по-синьо и по-малко контрастно заради слоя въздух."}},{"id":"gallery.art.vocab.t10","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Getty AAT: local color","url":"https://vocab.getty.edu/page/aat/300056135"}],"review":{"status":"legacy","fixes":["G046","G047","G048","G049"]},"kind":"term","term":{"label":"Локален цвят (Local colour)","bg":"Локален цвят","en":"Local colour","alts":["local colour","локален цвят","local color"],"def":"Собственият цвят на предмета, без влиянието на светлината и средата."}},{"id":"gallery.art.vocab.t11","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Getty AAT: colorito","url":"https://vocab.getty.edu/page/aat/300266723"}],"review":{"status":"legacy","fixes":["G050","G051","G052","G053"]},"kind":"term","term":{"label":"Колорит (Colouring)","bg":"Колорит","en":"Colouring","alts":["colouring","колорит","coloring","colorito"],"def":"Общият цветови строй на творбата — топъл, студен, ограничен, наситен."}},{"id":"gallery.art.vocab.t12","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Complementary colours","url":"https://www.tate.org.uk/art/art-terms/c/complementary-colours"}],"review":{"status":"legacy","fixes":["G054","G055","G056","G057"]},"kind":"term","term":{"label":"Комплементарни цветове (Complementary colours)","bg":"Комплементарни цветове","en":"Complementary colours","alts":["complementary colours","комплементарни цветове","complementary colors"],"def":"Срещуположни в цветния кръг (синьо–оранжево, червено–зелено); заедно дават най-силния възможен контраст."}},{"id":"gallery.art.vocab.t13","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Impasto","url":"https://www.tate.org.uk/art/art-terms/i/impasto"}],"review":{"status":"legacy","fixes":["G058","G059","G060","G061"]},"kind":"term","term":{"label":"Импасто (Impasto)","bg":"Импасто","en":"Impasto","alts":["impasto","импасто"],"def":"Дебел релефен слой боя, който запазва следата от четката или шпаклата."}},{"id":"gallery.art.vocab.t14","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"National Gallery, Glossary: Pointillist","url":"https://www.nationalgallery.org.uk/paintings/glossary/pointillist"},{"title":"Getty AAT: Pointillist (style)","url":"https://vocab.getty.edu/page/aat/300419441"}],"review":{"status":"legacy","fixes":["G062","G063","G064","G065"]},"kind":"term","term":{"label":"Пуантилизъм (Pointillism)","bg":"Пуантилизъм","en":"Pointillism","alts":["pointillism","пуантилизъм","pointillist"],"def":"Изображение от отделни точки чист цвят, които окото смесва вместо палитрата."}},{"id":"gallery.art.vocab.t15","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Getty AAT: stylization","url":"https://vocab.getty.edu/page/aat/300055836"}],"review":{"status":"legacy","fixes":["G066","G067","G068","G069"]},"kind":"term","term":{"label":"Стилизация (Stylisation)","bg":"Стилизация","en":"Stylisation","alts":["stylisation","стилизация","stylization"],"def":"Съзнателно свеждане на формата до нейния най-носещ знак — избор какво да остане."}},{"id":"gallery.art.vocab.t16","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Getty AAT: abstraction","url":"https://vocab.getty.edu/page/aat/300056508"},{"title":"Tate Art Terms: Abstract art","url":"https://www.tate.org.uk/art/art-terms/a/abstract-art"}],"review":{"status":"legacy","fixes":["G070","G071","G072","G073"]},"kind":"term","term":{"label":"Абстракция (Abstraction)","bg":"Абстракция","en":"Abstraction","alts":["abstraction","абстракция","abstract art"],"def":"Изображение без разпознаваем предмет; действа само чрез форма, цвят, ритъм и мащаб."}},{"id":"gallery.art.vocab.t17","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Iconography","url":"https://www.tate.org.uk/art/art-terms/i/iconography"}],"review":{"status":"legacy","fixes":["G074","G075","G076","G077"]},"kind":"term","term":{"label":"Иконография (Iconography)","bg":"Иконография","en":"Iconography","alts":["iconography","иконография"],"def":"Установеният набор от символи и начини на изобразяване на даден сюжет, по който го разпознаваме."}},{"id":"gallery.art.vocab.t18","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Readymade","url":"https://www.tate.org.uk/art/art-terms/r/readymade"}],"review":{"status":"legacy","fixes":["G078","G079","G080","G081"]},"kind":"term","term":{"label":"Реди-мейд (Readymade)","bg":"Реди-мейд","en":"Readymade","alts":["readymade","реди-мейд","ready-made"],"def":"Готов, непроменен предмет, обявен за произведение на изкуството (Дюшан)."}},{"id":"gallery.art.vocab.t19","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Photomontage","url":"https://www.tate.org.uk/art/art-terms/p/photomontage"},{"title":"Tate Art Terms: Dada","url":"https://www.tate.org.uk/art/art-terms/d/dada"}],"review":{"status":"legacy","fixes":["G082","G083","G084","G085","E119"]},"kind":"term","term":{"label":"Фотомонтаж (Photomontage)","bg":"Фотомонтаж","en":"Photomontage","alts":["photomontage","фотомонтаж"],"def":"Композиция от изрязани и съчетани снимки и печатни материали; изобретение на дада (Dada)."}},{"id":"gallery.art.vocab.t20","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Tate Art Terms: Fresco","url":"https://www.tate.org.uk/art/art-terms/f/fresco"}],"review":{"status":"legacy","fixes":["G086","G087","G088","G089"]},"kind":"term","term":{"label":"Фреска (Fresco)","bg":"Фреска","en":"Fresco","alts":["fresco","фреска"],"def":"Живопис върху прясна варова мазилка — цветът влиза в стената и става част от нея."}},{"id":"gallery.art.vocab.t21","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Getty AAT: golden section","url":"https://vocab.getty.edu/page/aat/300056300"}],"review":{"status":"legacy","fixes":["G090","G091","G092","G093"]},"kind":"term","term":{"label":"Златно сечение (Golden section)","bg":"Златно сечение","en":"Golden section","alts":["golden section","златно сечение","golden ratio","golden mean"],"def":"Деление в отношение приблизително 1:1,618, използвано за „естествено“ равновесие в композицията."}},{"id":"gallery.art.vocab.t22","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Getty AAT: silhouettes","url":"https://vocab.getty.edu/page/aat/300015423"}],"review":{"status":"legacy","fixes":["G094","G095","G096","G097"]},"kind":"term","term":{"label":"Силует (Silhouette)","bg":"Силует","en":"Silhouette","alts":["silhouette","силует"],"def":"Плътната външна форма на фигурата. Ако силуетът не се чете в черно, позата не работи."}},{"id":"gallery.art.vocab.t23","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Getty AAT: rhythm (artistic concept)","url":"https://vocab.getty.edu/page/aat/300056305"}],"review":{"status":"legacy","fixes":["G098","G099","G100","G101"]},"kind":"term","term":{"label":"Ритъм (Rhythm)","bg":"Ритъм","en":"Rhythm","alts":["rhythm","ритъм"],"def":"Повторение с интервал — то задава темпото, с което погледът минава през творбата."}},{"id":"gallery.art.vocab.t24","hall":"gallery","domain":"art","topic":"art.vocab","level":12,"subjects":["art"],"sources":[{"title":"Wikipedia: Hierarchical proportion","url":"https://en.wikipedia.org/wiki/Hierarchical_proportion"}],"review":{"status":"legacy","fixes":["G102","G103","G104","G105"]},"kind":"term","term":{"label":"Йерархичен мащаб (Hierarchical scale)","bg":"Йерархичен мащаб","en":"Hierarchical scale","alts":["hierarchical scale","йерархичен мащаб","hieratic scale","hierarchical proportion"],"def":"Размерът показва важност, а не разстояние — по-значимият е по-голям."}}]');export{t as default};
